;; Generated by the release tooling; do not edit.
(ns rainbow.coverage.total-test
  "Structural coverage guard: each proof module must be reachable from a test's
  namespace imports. This inventories test routes; only executing those tests
  establishes that declarations were kernel-checked. Pending modules fail."
  (:require [clojure.edn :as edn]
            [clojure.java.io :as io]
            [clojure.string :as string]
            [clojure.test :refer [deftest is]]))

(defn- clj-files [dir]
  (filter #(string/ends-with? (.getName ^java.io.File %) ".clj") (file-seq (io/file dir))))

(defn- lib-names [spec]
  (cond
    (symbol? spec) #{(str spec)}
    (sequential? spec)
    (let [[prefix & options] spec]
      (if (and (seq options) (not (keyword? (first options))))
        (set (for [child options
                   lib (lib-names child)]
               (str prefix "." lib)))
        #{(str prefix)}))
    :else #{}))

(defn- ns-and-requires [f]
  (let [t (slurp f)
        form (binding [*read-eval* false]
               (read (java.io.PushbackReader. (java.io.StringReader. t))))]
    (when-not (and (seq? form) (= 'ns (first form)) (symbol? (second form)))
      (throw (ex-info "source must start with a namespace declaration" {:file (str f)})))
    [(str (second form))
     (set (mapcat lib-names
                  (mapcat rest (filter #(and (seq? %) (#{:require :use} (first %)))
                                       (drop 2 form)))))
     t]))

(defn- coverage-problems [src tests pending]
  (let [requires (into {} (map (fn [[n r _]] [n r]) (concat src tests)))
        proof (set (keep (fn [[n _ t]]
                           (when (re-find #"\(defn\s+extend-environment[\s\[]" t) n)) src))
        reached (loop [seen #{} todo (vec (mapcat second tests))]
                  (if-let [x (peek todo)]
                    (if (seen x) (recur seen (pop todo))
                        (recur (conj seen x) (into (pop todo) (requires x))))
                    seen))]
    (cond-> {}
      (empty? src) (assoc :no-source true)
      (empty? tests) (assoc :no-tests true)
      (empty? proof) (assoc :no-proof-modules true)
      (seq pending) (assoc :pending (vec (sort pending)))
      (seq (remove reached proof)) (assoc :missing (vec (sort (remove reached proof)))))))

(deftest every-proof-module-is-reached-by-a-test
  (let [src (mapv ns-and-requires (clj-files "src"))
        tests (mapv ns-and-requires (clj-files "test"))
        pending (edn/read-string (slurp "test/rainbow/coverage/pending.edn"))
        problems (coverage-problems src tests pending)]
    (is (set? pending) "the pending inventory must be an empty set")
    (is (empty? problems) (str "proof coverage is incomplete: " (pr-str problems)))))
